// Build the 90-day probation review email. Branches on context.outcome:
//   'regularized'       → congratulations + welcome to full-time
//   'failed_probation'  → factual non-pass notice
//   undefined           → preview to direct supervisor + lead (decision pending)
// Inbound payload:
//   { onboarderId, template:'90-day-review', event, context: {
//     full_name, first_name, personal_email, role_title, onboarding_lead,
//     direct_supervisor, outcome?
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const firstName        = ctx.first_name        || (ctx.full_name || 'there').split(' ')[0];
const toEmail          = ctx.personal_email    || body.to;
const onboardingLead   = ctx.onboarding_lead   || 'Erich';
const directSupervisor = ctx.direct_supervisor || 'your supervisor';
const roleTitle        = ctx.role_title        || '';
const outcome          = ctx.outcome           || 'pending';

if (!toEmail) {
  throw new Error('No personal_email on context — cannot send 90-day review');
}

let subject;
let body_;
if (outcome === 'regularized') {
  subject = '90-day review — Welcome to the team full-time! | Romega Solutions';
  body_ = `Hi ${firstName},

Congratulations — you've successfully completed your 90-day probation${roleTitle ? ` as ${roleTitle}` : ''} at Romega. We're delighted to confirm you as a regularized member of the team.

What changes:
  • You're no longer on probation.
  • Your role, scope, and compensation continue as agreed in your SOW.
  • ${directSupervisor} will continue as your direct supervisor.

Thank you for the work and energy you've brought to the first three months. Looking forward to building with you.

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;
} else if (outcome === 'failed_probation') {
  subject = '90-day review — Outcome | Romega Solutions';
  body_ = `Hi ${firstName},

This email confirms the outcome of your 90-day probation review at Romega. After consultation with ${directSupervisor} and the leadership team, we won't be moving forward with regularization.

We'll send a separate note covering the handoff plan, final pay, and equipment return.

Thank you for your contributions during these three months. We wish you the best in what's next.

Regards,
${onboardingLead}
Onboarding Lead, Romega Solutions`;
} else {
  // Decision-pending preview: sent to lead + supervisor, not the new hire.
  subject = `90-day review preview — ${ctx.full_name || 'New hire'} | DECISION PENDING`;
  body_ = `Hi ${onboardingLead},

This is the 90-day review preview for ${ctx.full_name || 'this new hire'}${roleTitle ? ` (${roleTitle})` : ''}. Decision is pending — make the call in the app, then re-fire this workflow with outcome='regularized' or 'failed_probation' to send the final letter to the hire.

Direct supervisor: ${directSupervisor}

— Onboarding bot`;
}

return [{ json: { to: toEmail, subject, body: body_, onboarderId: body.onboarderId, template: '90-day-review', outcome } }];
